4	.button {
5	  display: inline-flex;
6	  align-items: center;
7	  gap: 6px;
8	  padding: 6px 14px;
9	  border: 1px solid var(--border-line);
10	  border-radius: var(--radius-pill);
11	  background: var(--bg-surface);
12	  color: var(--text-muted);
13	  font-family: var(--font-ui);
14	  font-size: var(--fs-tag);
15	  font-weight: 500;
16	  letter-spacing: var(--tracking-tag);
17	  text-transform: uppercase;
18	  cursor: pointer;
19	  transition:
20	    color var(--transition-fast),
21	    background var(--transition-fast),
22	    border-color var(--transition-fast);
23	}
24	
25	.button:hover:not(:disabled),
26	.button:focus-visible:not(:disabled) {
27	  border-color: var(--border-line-hover);
28	  color: var(--text);
29	  /* Suppress the browser default outline so the styled border-color
30	     swap is the single, unambiguous focus affordance. */
31	  outline: none;
32	}
33	
34	.button:disabled {
35	  cursor: default;
36	  opacity: 0.6;
37	}
38	
39	.liked {
40	  color: var(--like);
41	  border-color: rgba(224, 123, 123, 0.4);
42	  background: var(--like-tint);
43	}
44	.liked:hover:not(:disabled),
45	.liked:focus-visible:not(:disabled) {
46	  color: var(--like);
47	  border-color: rgba(224, 123, 123, 0.55);
48	  outline: none;
49	}
50	
51	.icon {
52	  width: 13px;
53	  height: 13px;
54	  display: inline-flex;
55	  flex-shrink: 0;
56	  transition: fill var(--transition-fast);
57	}
58	
59	.iconFilled {
60	  fill: var(--like);
61	  stroke: var(--like);
62	}
63	.iconOutline {
64	  fill: none;
65	  stroke: currentColor;
66	}
67	
68	.count {
69	  font-variant-numeric: tabular-nums;
70	}
71	
72	/* Touch-target sizing — bump padding so the pill clears 44px tall
73	   on phones. Desktop stays dense; the like / save / share footer
74	   row reads as one tight cluster there. */
75	@media (max-width: 720px) {
76	  .button {
77	    padding: 11px 16px;
78	  }
79	}
